resources.afterResponseScript:
insomnia.test('returns 201 Created', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
});
const wallet = insomnia.response.json();
insomnia.test('creates an active INR wallet with zero balance', () => {
  insomnia.expect(wallet.status).to.eql('ACTIVE');
  insomnia.expect(wallet.currency).to.eql('INR');
  insomnia.expect(wallet.balanceMinorUnits).to.eql(0);
  insomnia.expect(wallet.heldBalanceMinorUnits).to.eql(0);
  insomnia.expect(wallet.availableBalanceMinorUnits).to.eql(0);
  insomnia.expect(wallet.id).to.be.a('string');
});
insomnia.environment.set('wallet_id', wallet.id);
insomnia.environment.set('topup_idempotency_key', 'insomnia-smoke-' + wallet.id);
insomnia.environment.set('payment_idempotency_key', 'payment-' + wallet.id);

insomnia.test('returns 200 OK', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});
const wallet = insomnia.response.json();
insomnia.test('wallet starts with zero balance', () => {
  insomnia.expect(wallet.id).to.eql(insomnia.environment.get('wallet_id'));
  insomnia.expect(wallet.balanceMinorUnits).to.eql(0);
  insomnia.expect(wallet.status).to.eql('ACTIVE');
});

insomnia.test('returns 200 OK', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});
const result = insomnia.response.json();
insomnia.test('funds the wallet with the configured amount', () => {
  insomnia.expect(result.walletId).to.eql(insomnia.environment.get('wallet_id'));
  insomnia.expect(result.amountMinorUnits).to.eql(Number(insomnia.environment.get('topup_amount_minor_units')));
  insomnia.expect(result.currency).to.eql('INR');
  insomnia.expect(result.journalEntryId).to.be.a('string');
});
insomnia.environment.set('topup_id', result.id);
insomnia.environment.set('topup_journal_entry_id', result.journalEntryId);
insomnia.environment.set('topup_transaction_reference', result.transactionReference);

insomnia.test('returns the original top-up result', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});
const result = insomnia.response.json();
insomnia.test('retry is idempotent', () => {
  insomnia.expect(result.id).to.eql(insomnia.environment.get('topup_id'));
  insomnia.expect(result.journalEntryId).to.eql(insomnia.environment.get('topup_journal_entry_id'));
});

insomnia.test('returns 200 OK', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});
const wallet = insomnia.response.json();
insomnia.test('balance matches the top-up amount', () => {
  insomnia.expect(wallet.balanceMinorUnits).to.eql(Number(insomnia.environment.get('topup_amount_minor_units')));
  insomnia.expect(wallet.currency).to.eql('INR');
});

insomnia.test('returns 200 OK', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});
const page = insomnia.response.json();
insomnia.test('history contains one balanced top-up posting for the fresh wallet', () => {
  insomnia.expect(page.totalElements).to.eql(1);
  insomnia.expect(page.transactions[0].journalEntryId).to.eql(insomnia.environment.get('topup_journal_entry_id'));
  insomnia.expect(page.transactions[0].transactionReference).to.eql(insomnia.environment.get('topup_transaction_reference'));
  insomnia.expect(page.transactions[0].side).to.eql('CREDIT');
  insomnia.expect(page.transactions[0].amountMinorUnits).to.eql(Number(insomnia.environment.get('topup_amount_minor_units')));
});

insomnia.test('returns 409 Conflict', () => {
  insomnia.expect(insomnia.response.code).to.eql(409);
});
const problem = insomnia.response.json();
insomnia.test('returns the typed idempotency error', () => {
  insomnia.expect(problem.errorCode).to.eql('IDEMPOTENCY_KEY_REUSED');
});

insomnia.test('returns 400 Bad Request', () => {
  insomnia.expect(insomnia.response.code).to.eql(400);
});
const problem = insomnia.response.json();
insomnia.test('returns a safe validation error', () => {
  insomnia.expect(problem.errorCode).to.eql('INVALID_WALLET_REQUEST');
  insomnia.expect(problem.detail).to.be.a('string');
});

insomnia.test('returns 201 Created', () => { insomnia.expect(insomnia.response.code).to.eql(201); });
const hold = insomnia.response.json();
insomnia.test('creates an active hold against this wallet', () => {
  insomnia.expect(hold.walletId).to.eql(insomnia.environment.get('wallet_id'));
  insomnia.expect(hold.amountMinorUnits).to.eql(20000);
  insomnia.expect(hold.status).to.eql('ACTIVE');
});
insomnia.environment.set('hold_id', hold.id);

insomnia.test('returns 200 OK', () => { insomnia.expect(insomnia.response.code).to.eql(200); });
const page = insomnia.response.json();
insomnia.test('lists the active hold for this wallet', () => {
  insomnia.expect(page.totalElements).to.eql(1);
  insomnia.expect(page.holds[0].walletId).to.eql(insomnia.environment.get('wallet_id'));
  insomnia.expect(page.holds[0].status).to.eql('ACTIVE');
});
insomnia.environment.set('hold_id', page.holds[0].id);

insomnia.test('returns 409 Conflict', () => { insomnia.expect(insomnia.response.code).to.eql(409); });
const problem = insomnia.response.json();
insomnia.test('reports insufficient available funds', () => { insomnia.expect(problem.errorCode).to.eql('INSUFFICIENT_AVAILABLE_BALANCE'); });

insomnia.test('returns 200 OK', () => { insomnia.expect(insomnia.response.code).to.eql(200); });
const wallet = insomnia.response.json();
insomnia.test('hold reduces available balance only', () => {
  insomnia.expect(wallet.balanceMinorUnits).to.eql(65000);
  insomnia.expect(wallet.heldBalanceMinorUnits).to.eql(20000);
  insomnia.expect(wallet.availableBalanceMinorUnits).to.eql(45000);
});

insomnia.test('returns 200 OK', () => { insomnia.expect(insomnia.response.code).to.eql(200); });
const hold = insomnia.response.json();
insomnia.test('marks the hold released', () => { insomnia.expect(hold.status).to.eql('RELEASED'); });

insomnia.test('returns 200 OK', () => { insomnia.expect(insomnia.response.code).to.eql(200); });
const wallet = insomnia.response.json();
insomnia.test('released hold restores available balance', () => {
  insomnia.expect(wallet.heldBalanceMinorUnits).to.eql(0);
  insomnia.expect(wallet.availableBalanceMinorUnits).to.eql(65000);
});

insomnia.test('returns configured wallet policy', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  insomnia.expect(insomnia.response.json().allowedMerchantIds).to.include('foodapp-demo');
});

insomnia.test('returns 201 Created', () => { insomnia.expect(insomnia.response.code).to.eql(201); });
const payment = insomnia.response.json();
insomnia.test('creates a payment ready for authorization', () => {
  insomnia.expect(payment.status).to.eql('CREATED');
  insomnia.expect(payment.amountMinorUnits).to.eql(20000);
});
insomnia.environment.set('payment_id', payment.id);

insomnia.test('returns the original payment', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
  insomnia.expect(insomnia.response.json().id).to.eql(insomnia.environment.get('payment_id'));
});

insomnia.test('returns 200 OK', () => { insomnia.expect(insomnia.response.code).to.eql(200); });
const payment = insomnia.response.json();
insomnia.test('authorizes the payment and creates a hold', () => {
  insomnia.expect(payment.status).to.eql('AUTHORIZED');
  insomnia.expect(payment.authorizationHoldId).to.be.a('string');
});

insomnia.test('returns 200 OK', () => { insomnia.expect(insomnia.response.code).to.eql(200); });
const wallet = insomnia.response.json();
insomnia.test('payment authorization reserves funds', () => {
  insomnia.expect(wallet.heldBalanceMinorUnits).to.eql(20000);
  insomnia.expect(wallet.availableBalanceMinorUnits).to.eql(45000);
});

insomnia.test('creates a matched reconciliation batch', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
  insomnia.expect(insomnia.response.json().status).to.eql('MATCHED');
  insomnia.expect(insomnia.response.json().breakCount).to.eql(0);
});

insomnia.test('stores a reconciliation break', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
  insomnia.expect(insomnia.response.json().status).to.eql('BREAKS_FOUND');
  insomnia.expect(insomnia.response.json().breakCount).to.be.above(0);
});
insomnia.environment.set('reconciliation_batch_id', insomnia.response.json().id);

insomnia.test('returns stored reconciliation breaks', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  insomnia.expect(insomnia.response.json().breaks.length).to.be.above(0);
});

insomnia.test('human approval authorizes the pending payment', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  insomnia.expect(insomnia.response.json().status).to.eql('AUTHORIZED');
});

insomnia.test('creates a one-time INR spend mandate', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
  insomnia.expect(insomnia.response.json().status).to.eql('ACTIVE');
  insomnia.expect(insomnia.response.json().maxAmountMinorUnits).to.eql(12000);
});
insomnia.environment.set('spend_mandate_id', insomnia.response.json().id);

insomnia.test('creates an authorized payment within mandate limits', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  insomnia.expect(insomnia.response.json().status).to.eql('AUTHORIZED');
});
insomnia.environment.set('mandate_payment_id', insomnia.response.json().id);

insomnia.test('returns the same payment for a retry', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  insomnia.expect(insomnia.response.json().id).to.eql(insomnia.environment.get('mandate_payment_id'));
});

insomnia.test('does not allow a mandate to be spent twice', () => {
  insomnia.expect(insomnia.response.code).to.eql(409);
  insomnia.expect(insomnia.response.json().errorCode).to.eql('MANDATE_CONSUMED');
});
